pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function testFuzz_property(uint256 warpTo, uint256 unlockTime, uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        warpTo = bound(warpTo, 1, type(uint64).max);
        vm.warp(warpTo);
        uint256 late = unlockTime > warpTo ? unlockTime : warpTo + 1;
        // property: depositing with any past unlockTime must still lock funds until now
        // past unlock time (admissible input): unlockTime <= warpTo
        unlockTime = bound(unlockTime, 0, warpTo);
        amount = bound(amount, 1, type(uint96).max);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (, uint256 bal) = c.Acc(actor);
        // the stored clamp guarantees Collect fails while block.timestamp <= deposit-time lock
        vm.prank(actor);
        try c.Collect(amount) {
            assertTrue(false, "withdraw succeeded before unlock time");
        } catch {
            assertTrue(true);
        }
    }
}

