pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 _unlockTime, uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 t = 1_000_000;
        vm.warp(t);
        // deposit time is strictly in the past relative to now
        _unlockTime = bound(_unlockTime, 0, t - 1);
        // enough so the account balance reaches MinSum (1 ether)
        amount = bound(amount, 1 ether, 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(_unlockTime);

        // immediate withdrawal attempt in the same block
        vm.prank(actor);
        bool ok;
        try c.Collect(amount) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "withdraw succeeded at the deposit-time lock");
    }
}

