import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(uint256 amount, uint256 lockTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);
        // Rule: a deposit never stores an unlockTime in the past relative to the deposit block.
        assertTrue(c.Acc(actor).unlockTime >= block.timestamp);
    }
}

