pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 pastDelta) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether, 100 ether);
        pastDelta = bound(pastDelta, 1, 365 days);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp - pastDelta);

        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));

        assertTrue(!ok, "Collect must revert before unlockTime");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 msgValue, uint256 pastTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        // avoid overflow in (acc.balance + msg.value) and satisfy MinSum for Collect
        msgValue = bound(msgValue, 1 ether, 1 ether * 1e9);
        pastTime = bound(pastTime, 0, block.timestamp - 1); // strictly in the past
        vm.deal(actor, msgValue);
        vm.prank(actor);
        c.Put{value: msgValue}(pastTime);
        vm.prank(actor);
        bool withdrawn;
        try c.Collect(msgValue) { withdrawn = true; } catch { withdrawn = false; }
        // General rule: an immediate withdrawal in the same block as the deposit
        // must be impossible, since the unlock time is clamped to at least now.
        assertTrue(!withdrawn);
    }
}

