pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        assertTrue(c.Acc(actor).balance == amount, "deposit must be credited");
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amt, uint am) public
    {
        require(amt >= 1 ether);
        require(am > 0 && am <= amt - 1 ether);
        require(address(this).balance >= amt);

        c.Put{value: amt}(0);
        c.Collect(am);

        (, uint bal) = c.Acc(address(this));
        assert(bal == amt - am);
    }

    receive() external payable {}
}

