contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test(uint am) public
    {
        require(am < c.MinSum());
        require(address(this).balance >= am);

        c.Put{value: am}(0);

        // time may have advanced past unlockTime now; in P the MinSum guard
        // still blocks, in M it does not.
        c.Collect(am);

        assert(c.Acc(address(this)).balance == am);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint v) public {
        require(v >= 1 ether);
        require(address(this).balance >= v);
        c.Put{value: v}(0);
        c.Collect(v);
        assert(c.Acc(address(this)).balance == v);
    }
